import { Controller, Get, Logger, Param } from "@nestjs/common";
import { EventPattern, MessagePattern } from "@nestjs/microservices";

import { AppService } from "./app.service.js";

interface AuditEvent {
  id: string;
  payload: Record<string, unknown>;
  source: string;
}

const isAuditEvent = (value: unknown): value is AuditEvent => {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === "string" &&
    candidate.id.trim().length > 0 &&
    typeof candidate.source === "string" &&
    candidate.source.trim().length > 0 &&
    typeof candidate.payload === "object" &&
    candidate.payload !== null &&
    !Array.isArray(candidate.payload)
  );
};

@Controller()
export class AppController {
  private readonly logger = new Logger(AppController.name);

  constructor(private readonly appService: AppService) {}


  @Get()
  getHello(): string {
    return this.appService.getHello();
  }

  @Get("events/:id")
  getAuditEvent(
    @Param("id") id: string
  ): { id: string; payload: Record<string, unknown>; source: string } | null {
    return this.appService.getAuditEvent(id);
  }

  @EventPattern("audit")
  handleAuditEvent(data: unknown): void {
    if (!isAuditEvent(data)) {
      this.logger.warn("Discarded malformed audit event payload");
      return;
    }
    this.appService.recordAuditEvent(data);
  }

  @MessagePattern("ping")
  handlePing(): string {
    return this.appService.handlePing();
  }

  @MessagePattern("log")
  handleLog(data: Record<string, unknown>): { received: Record<string, unknown> } {
    return this.appService.handleLog(data);
  }
}

import { Module } from "@nestjs/common";

import { AppController } from "./app.controller.js";
import { AppService } from "./app.service.js";

@Module({
  controllers: [AppController],
  imports: [
  ],
  providers: [
    AppService,
  ],
})
export class AppModule {}

import { Injectable } from "@nestjs/common";

@Injectable()
export class AppService {
  private readonly auditEvents = new Map<
    string,
    { id: string; payload: Record<string, unknown>; source: string }
  >();

  recordAuditEvent(event: {
    id: string;
    payload: Record<string, unknown>;
    source: string;
  }): void {
    this.auditEvents.set(event.id, event);
  }

  getAuditEvent(
    id: string
  ): { id: string; payload: Record<string, unknown>; source: string } | null {
    return this.auditEvents.get(id) ?? null;
  }

  getHello(): string {
    return "Hello World!";
  }

  handlePing(): string {
    return "pong";
  }

  handleLog(data: Record<string, unknown>): { received: Record<string, unknown> } {
    return { received: data };
  }
}

import { Logger, StandardSchemaValidationPipe } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";
import { Transport } from "@nestjs/microservices";
import type { MicroserviceOptions } from "@nestjs/microservices";

import { AppModule } from "./app.module.js";
import { env } from "./config/env.js";

async function bootstrap() {
  const trustedProxyIps = env.TRUSTED_PROXY_IPS.split(",").map((ip) => ip.trim()).filter(Boolean);
  const app = await NestFactory.create(AppModule);
  if (trustedProxyIps.length > 0) {
    app.getHttpAdapter().getInstance().set("trust proxy", trustedProxyIps);
  }
  app.enableCors({ origin: env.CORS_ORIGIN });
  app.setGlobalPrefix("api");
  app.useGlobalPipes(new StandardSchemaValidationPipe());
  app.enableShutdownHooks();

  app.connectMicroservice<MicroserviceOptions>({
    options: {
      host: new URL(env.REDIS_URL).hostname,
      port: Number(new URL(env.REDIS_URL).port || 6379),
    },
    transport: Transport.REDIS,
  });


  await app.startAllMicroservices();
  await app.listen(env.PORT ?? 3000, "0.0.0.0");
  Logger.log(`Started server on http://localhost:${env.PORT ?? 3000}`, "Main");
  }
await bootstrap();

import type { INestApplication } from "@nestjs/common";
import { Test } from "@nestjs/testing";
import { afterAll, expect, it } from "vitest";

import { AppModule } from "../src/app.module.js";

let app: INestApplication;

it("serves the generated HTTP application", async () => {
  const module = await Test.createTestingModule({ imports: [AppModule] }).compile();
  app = module.createNestApplication();
  app.setGlobalPrefix("api");
  await app.init();
  expect(app.getHttpServer()).toBeDefined();
});

afterAll(async () => {
  await app?.close();
});

